const MODULE_META = {"technical-indicators":{"terms":["Moving average","RSI","MACD","Volatility","Volume","Divergence"],"tools":"ALL_INDICATORS","calc":[]}};
const MODULE_CONTENT = {"en":{"technical-indicators":{"faq":[{"q":"How many indicators should I use?","a":"Two or three that measure different things. Adding more often repeats the same information and makes decisions harder."},{"q":"Why do two indicators give different signals?","a":"They measure different things and use different lengths. A trend tool may still say up while a momentum tool shows overbought. Use the disagreement as information, not as a reason to ignore one of them."},{"q":"Can indicators predict the price?","a":"No. They are calculated from past data. They help you understand the current state and manage risk, but they do not predict with certainty."}],"quiz":[{"q":"Which indicator measures trend strength but not direction?","o":["ADX","RSI","MACD","Volume"],"a":0,"e":"ADX shows how strong a trend is; the +DI and -DI lines show direction."},{"q":"The main use of ATR is:","o":["Predicting direction","Measuring volatility to set stop distance and position size","Calculating dividends","Tracking fund fees"],"a":1,"e":"ATR measures typical daily movement, which helps size stops and positions."},{"q":"Which indicator confirms a breakout best?","o":["Bollinger Bands alone","A single candle","Volume above its average","The expiry date"],"a":2,"e":"A breakout on above-average volume has more participation behind it."},{"q":"Bollinger Bands are placed at:","o":["The highest and lowest price of the year","The dividend yield","The EPS level","Two standard deviations around a 20-period average"],"a":3,"e":"The bands are two standard deviations above and below the 20-period mean."},{"q":"A Bollinger squeeze (narrow bands) often comes before:","o":["A larger price move","A dividend","A stock split","No change"],"a":0,"e":"Low volatility often precedes an expansion in volatility and a larger move."},{"q":"On-balance volume (OBV) adds volume on days when:","o":["Price falls","Price closes higher","Volume is low","The market is closed"],"a":1,"e":"OBV adds volume on up closes and subtracts it on down closes."},{"q":"If price makes a new high but OBV does not, this suggests:","o":["Strengthening buyers","A stock split","Weakening buyers, a warning sign","A dividend"],"a":2,"e":"The lack of confirmation from volume is a warning of divergence."},{"q":"VWAP is best described as:","o":["The highest price of the session","The closing price of last week","The company's EPS","The average price weighted by volume for the session"],"a":3,"e":"VWAP is volume-weighted, and intraday traders use it as a reference line."},{"q":"The stochastic oscillator is most useful in:","o":["Sideways markets, to time entries near the edges of a range","Strong trends only","Dividend investing","Expiry-day trading only"],"a":0,"e":"It is quick and works well in ranges, but can stay overbought in strong trends."},{"q":"ADX above 25 generally suggests:","o":["A weak trend or range","A trend, which favours trend-following tools","A dividend","A stock split"],"a":1,"e":"Readings above 25 are commonly read as a trend."},{"q":"The main benefit of combining indicators from different families is:","o":["They all measure the same thing","They remove all risk","They measure different aspects, so they give more balanced information","They are required by SEBI"],"a":2,"e":"Different families cover trend, momentum, volatility and volume."},{"q":"Which is a common indicator mistake?","o":["Setting stops before entry","Testing on past data","Keeping a journal","Changing settings after seeing the result"],"a":3,"e":"Changing settings after the result is a form of curve-fitting."},{"q":"In a strong uptrend, RSI often stays:","o":["Between about 40 and 80","Below 20","Exactly at 50","Above 100"],"a":0,"e":"In strong trends RSI tends to hover in the upper-middle range."},{"q":"What does a falling ADX from high levels often mean?","o":["The trend is strengthening","The trend may be tiring","A new listing","A stock split"],"a":1,"e":"A declining ADX from high levels often signals a weakening trend."},{"q":"Why test an indicator with a fixed rule before trusting it?","o":["To find the best-looking chart","To avoid all losses","To measure whether the average result after costs is positive","To change the rule each week"],"a":2,"e":"Testing with fixed rules gives honest statistics on expectancy."},{"q":"Which indicator gives a running total of volume?","o":["RSI","ATR","Bollinger Bands","OBV"],"a":3,"e":"OBV is a cumulative volume total based on up and down closes."},{"q":"An RSI reading of 25 is best described as:","o":["Oversold, which may precede a bounce but is not certain","Overbought","A guaranteed buy","Neutral in all cases"],"a":0,"e":"Oversold readings can persist; they are not guarantees."},{"q":"The moving average of a 20-period window is calculated by:","o":["Dividing price by volume","Adding the last 20 closes and dividing by 20","Subtracting the low from the high","Counting green candles"],"a":1,"e":"A simple moving average is the mean of the last 20 closing prices."},{"q":"Which indicator is best for setting the distance of a stop-loss?","o":["Dividend yield","P/E ratio","ATR","Market capitalisation"],"a":2,"e":"ATR scales the stop to the stock's normal volatility."},{"q":"Which combination is a sensible beginner set?","o":["Ten momentum indicators","Only fundamental ratios","Only candle colours","One trend tool, one momentum tool, one volatility tool and volume"],"a":3,"e":"A small, balanced set avoids repeating the same information."}]}},"hi":{"technical-indicators":{"faq":[{"q":"मुझे कितने इंडिकेटर इस्तेमाल करने चाहिए?","a":"दो या तीन जो अलग चीज़ें मापें। और जोड़ने से अक्सर एक ही जानकारी दोहराई जाती है और फ़ैसला कठिन होता है।"},{"q":"दो इंडिकेटर अलग संकेत क्यों देते हैं?","a":"वे अलग चीज़ें मापते हैं और अलग अवधियाँ इस्तेमाल करते हैं। ट्रेंड टूल अभी भी ऊपर कह सकता है जबकि मोमेंटम टूल ओवरबॉट दिखाए। इस असहमति को जानकारी मानें, किसी एक को नज़रअंदाज़ करने का कारण नहीं।"},{"q":"क्या इंडिकेटर कीमत की भविष्यवाणी कर सकते हैं?","a":"नहीं। ये पिछले डेटा से बनते हैं। ये मौजूदा स्थिति समझने और जोखिम संभालने में मदद करते हैं, पर निश्चितता से भविष्यवाणी नहीं करते।"}],"quiz":[{"q":"कौन सा इंडिकेटर ट्रेंड की ताकत मापता है, दिशा नहीं?","o":["ADX","RSI","MACD","वॉल्यूम"],"a":0,"e":"ADX ट्रेंड की ताकत दिखाता है; +DI और -DI दिशा दिखाती हैं।"},{"q":"ATR का मुख्य उपयोग है:","o":["दिशा की भविष्यवाणी","अस्थिरता मापकर स्टॉप की दूरी और पोज़िशन साइज़ तय करना","डिविडेंड की गणना","फंड फ़ीस ट्रैक करना"],"a":1,"e":"ATR सामान्य दैनिक चाल मापता है, जो स्टॉप और पोज़िशन तय करने में मदद करता है।"},{"q":"ब्रेकआउट की पुष्टि के लिए कौन सा इंडिकेटर सबसे अच्छा है?","o":["केवल बोलिंगर बैंड","एक अकेली कैंडल","औसत से ज़्यादा वॉल्यूम","एक्सपायरी तारीख़"],"a":2,"e":"औसत से ज़्यादा वॉल्यूम पर ब्रेकआउट के पीछे ज़्यादा भागीदारी होती है।"},{"q":"बोलिंगर बैंड कहाँ लगते हैं?","o":["साल का सबसे ऊँचा और सबसे नीचा भाव","डिविडेंड यील्ड पर","EPS स्तर पर","20-अवधि एवरेज के चारों ओर दो मानक विचलन पर"],"a":3,"e":"बैंड 20-अवधि के माध्य के ऊपर और नीचे दो मानक विचलन पर होते हैं।"},{"q":"बोलिंगर स्क्वीज़ (संकरे बैंड) अक्सर किससे पहले आते हैं?","o":["बड़ी कीमत चाल","डिविडेंड","स्टॉक स्प्लिट","कोई बदलाव नहीं"],"a":0,"e":"कम अस्थिरता अक्सर बढ़ी अस्थिरता और बड़ी चाल से पहले होती है।"},{"q":"ऑन-बैलेंस वॉल्यूम (OBV) वॉल्यूम कब जोड़ता है?","o":["जब कीमत गिरे","जब कीमत ऊपर बंद हो","जब वॉल्यूम कम हो","जब बाज़ार बंद हो"],"a":1,"e":"OBV ऊपर बंद होने वाले दिनों पर वॉल्यूम जोड़ता है और नीचे वाले दिनों पर घटाता है।"},{"q":"अगर कीमत नया हाई बनाए पर OBV नहीं, तो यह सुझाता है:","o":["ख़रीदार मज़बूत हो रहे हैं","स्टॉक स्प्लिट","ख़रीदार कमज़ोर हो रहे हैं, चेतावनी संकेत","डिविडेंड"],"a":2,"e":"वॉल्यूम से पुष्टि की कमी डाइवर्जेंस की चेतावनी है।"},{"q":"VWAP को सबसे अच्छा कैसे वर्णित किया जाए?","o":["सत्र का सबसे ऊँचा भाव","पिछले हफ़्ते का क्लोज़","कंपनी का EPS","सत्र के लिए वॉल्यूम से भारित औसत कीमत"],"a":3,"e":"VWAP वॉल्यूम-भारित है, और इंट्राडे ट्रेडर इसे संदर्भ रेखा की तरह देखते हैं।"},{"q":"स्टोकेस्टिक ऑसिलेटर सबसे ज़्यादा किसमें उपयोगी है?","o":["साइडवे बाज़ार में, रेंज के किनारों पर एंट्री का समय तय करने के लिए","केवल मज़बूत ट्रेंड में","डिविडेंड निवेश में","केवल एक्सपायरी दिन"],"a":0,"e":"यह तेज़ है और रेंज में अच्छा काम करता है, पर मज़बूत ट्रेंड में ओवरबॉट रह सकता है।"},{"q":"70 से ऊपर ADX आमतौर पर किसे सुझाता है?","o":["कमज़ोर ट्रेंड या रेंज","ट्रेंड, जो ट्रेंड-फ़ॉलोइंग टूल के पक्ष में है","डिविडेंड","स्टॉक स्प्लिट"],"a":1,"e":"25 से ऊपर के पाठ आमतौर पर ट्रेंड माने जाते हैं।"},{"q":"अलग-अलग परिवारों के इंडिकेटर मिलाने का मुख्य फ़ायदा क्या है?","o":["वे सब एक ही चीज़ मापते हैं","वे सारा जोखिम हटाते हैं","वे अलग पहलू मापते हैं, इसलिए जानकारी ज़्यादा संतुलित होती है","SEBI इसे अनिवार्य करता है"],"a":2,"e":"अलग परिवार ट्रेंड, मोमेंटम, अस्थिरता और वॉल्यूम कवर करते हैं।"},{"q":"इंडिकेटर की एक आम गलती कौन सी है?","o":["एंट्री से पहले स्टॉप तय करना","पिछले डेटा पर परखना","जर्नल रखना","नतीजा देखने के बाद सेटिंग बदलना"],"a":3,"e":"नतीजे के बाद सेटिंग बदलना एक तरह का curve-fitting है।"},{"q":"मज़बूत अपट्रेंड में RSI अक्सर रहता है:","o":["लगभग 40 से 80 के बीच","20 से नीचे","ठीक 50 पर","100 से ऊपर"],"a":0,"e":"मज़बूत ट्रेंड में RSI ऊपरी-मध्य रेंज में मँडराता है।"},{"q":"ऊँचे स्तर से गिरता ADX अक्सर क्या बताता है?","o":["ट्रेंड मज़बूत हो रहा है","ट्रेंड थक सकता है","नई लिस्टिंग","स्टॉक स्प्लिट"],"a":1,"e":"ऊँचे स्तर से गिरता ADX अक्सर कमज़ोर होते ट्रेंड का संकेत है।"},{"q":"भरोसे से पहले इंडिकेटर को तय नियम से क्यों परखें?","o":["सबसे अच्छा दिखने वाला चार्ट पाने के लिए","सारे नुकसान से बचने के लिए","खर्च के बाद औसत नतीजा सकारात्मक है या नहीं, यह मापने के लिए","हर हफ़्ते नियम बदलने के लिए"],"a":2,"e":"तय नियमों से परखने पर अपेक्षित मूल्य के ईमानदार आँकड़े मिलते हैं।"},{"q":"कौन सा इंडिकेटर वॉल्यूम का चलता कुल देता है?","o":["RSI","ATR","बोलिंगर बैंड","OBV"],"a":3,"e":"OBV ऊपर और नीचे बंद होने के आधार पर संचयी वॉल्यूम कुल है।"},{"q":"RSI का 25 का पाठ सबसे अच्छा कैसे वर्णित है?","o":["ओवरसोल्ड, जो उछाल से पहले हो सकता है पर निश्चित नहीं","ओवरबॉट","निश्चित ख़रीद","हर हाल में तटस्थ"],"a":0,"e":"ओवरसोल्ड पाठ बने रह सकते हैं; वे गारंटी नहीं हैं।"},{"q":"20-अवधि की विंडो का मूविंग एवरेज किससे निकलता है?","o":["कीमत को वॉल्यूम से भाग देने से","अंतिम 20 क्लोज़ को जोड़कर 20 से भाग देने से","हाई से लो घटाने से","हरी कैंडल गिनने से"],"a":1,"e":"सिंपल मूविंग एवरेज अंतिम 20 क्लोज़िंग कीमतों का माध्य है।"},{"q":"स्टॉप-लॉस की दूरी तय करने के लिए सबसे अच्छा इंडिकेटर कौन सा है?","o":["डिविडेंड यील्ड","P/E अनुपात","ATR","मार्केट कैपिटलाइज़ेशन"],"a":2,"e":"ATR स्टॉप को शेयर की सामान्य अस्थिरता के अनुपात में रखता है।"},{"q":"शुरुआती के लिए संतुलित सेट कौन सा है?","o":["दस मोमेंटम इंडिकेटर","केवल फंडामेंटल अनुपात","केवल कैंडल के रंग","एक ट्रेंड टूल, एक मोमेंटम टूल, एक अस्थिरता टूल और वॉल्यूम"],"a":3,"e":"छोटा और संतुलित सेट एक ही जानकारी दोहराने से बचाता है।"}]}}};
const PATTERNS = [];
const INDICATORS = [{"id":"moving-averages","file":"moving-averages.svg","category":"trend","name":{"en":"Moving averages (SMA and EMA)","hi":"मूविंग एवरेज (SMA और EMA)"},"what":{"en":"The average price over a set number of periods. SMA treats every period equally; EMA gives more weight to recent prices, so it reacts faster.","hi":"एक तय अवधि की औसत कीमत। SMA हर अवधि को बराबर वज़न देता है; EMA हाल की कीमतों को ज़्यादा वज़न देता है, इसलिए वह तेज़ी से प्रतिक्रिया देता है।"},"settings":{"en":"20 (short-term), 50 (medium), 200 (long-term) periods are common.","hi":"20 (अल्पकालिक), 50 (मध्यम), 200 (दीर्घकालिक) अवधि आम हैं।"},"when":{"en":"To judge trend direction. Use it in trending markets. In sideways markets it produces many false crossovers.","hi":"ट्रेंड की दिशा समझने के लिए। ट्रेंडिंग बाज़ार में उपयोग करें। साइडवे बाज़ार में यह कई झूठे क्रॉसओवर देता है।"},"how":{"en":"Swing trade: buy when price closes above the 20 EMA in an uptrend (50 SMA above 200 SMA). Put the stop below the 20 EMA or the last swing low. Exit when price closes below the 20 EMA. A 50 SMA crossing above the 200 SMA is a 'golden cross'; the reverse is a 'death cross'.","hi":"स्विंग ट्रेड: अपट्रेंड में जब कीमत 20 EMA के ऊपर बंद हो (50 SMA, 200 SMA के ऊपर) तब ख़रीदें। स्टॉप 20 EMA के नीचे या पिछले स्विंग लो के नीचे रखें। कीमत 20 EMA के नीचे बंद हो तो बाहर निकलें। 50 SMA का 200 SMA को ऊपर पार करना 'गोल्डन क्रॉस' है; उल्टा 'डेथ क्रॉस'।"},"mistake":{"en":"Buying every crossover in a sideways range. Also, a longer average lags more, so a 200-period average turns late.","hi":"साइडवे रेंज में हर क्रॉसओवर पर ख़रीदना। लंबा एवरेज ज़्यादा देर से चलता है, इसलिए 200 अवधि का एवरेज देर से पलटता है।"},"pairs":{"en":"ADX (is the trend strong?), volume (is the move supported?).","hi":"ADX (ट्रेंड मज़बूत है?), वॉल्यूम (चाल का समर्थन है?)।"}},{"id":"rsi","file":"rsi.svg","category":"momentum","name":{"en":"RSI (Relative Strength Index)","hi":"RSI (रिलेटिव स्ट्रेंथ इंडेक्स)"},"what":{"en":"Measures the speed and size of recent gains against recent losses, on a 0 to 100 scale.","hi":"हाल के लाभ और हानि की गति और आकार को 0 से 100 के पैमाने पर मापता है।"},"settings":{"en":"14 periods. Levels: 70 (overbought), 30 (oversold), 50 (midline).","hi":"14 अवधि। स्तर: 70 (ओवरबॉट), 30 (ओवरसोल्ड), 50 (मध्य रेखा)।"},"when":{"en":"In a range, to buy near oversold and sell near overbought. In a trend, to find pullback entries (RSI dips toward 40-50 and turns up).","hi":"रेंज में, ओवरसोल्ड के पास ख़रीदने और ओवरबॉट के पास बेचने के लिए। ट्रेंड में, पुलबैक एंट्री खोजने के लिए (RSI 40-50 तक गिरकर ऊपर मुड़े)।"},"how":{"en":"Uptrend pullback: price above the 50 SMA, RSI falls to 40-50 and turns up, buy. Stop below the pullback low. Range: buy when RSI closes back above 30, sell when it reaches 70. Divergence: price makes a higher high but RSI makes a lower high, a warning that momentum is fading.","hi":"अपट्रेंड पुलबैक: कीमत 50 SMA के ऊपर, RSI 40-50 तक गिरे और ऊपर मुड़े, तो ख़रीदें। स्टॉप पुलबैक के लो के नीचे। रेंज: RSI 30 के ऊपर वापस बंद हो तो ख़रीदें, 70 पर पहुँचे तो बेचें। डाइवर्जेंस: कीमत ऊँचा हाई बनाए पर RSI नीचा हाई, तो मोमेंटम कमज़ोर होने की चेतावनी।"},"mistake":{"en":"Selling just because RSI is above 70 in a strong uptrend. Strong trends can stay overbought for weeks.","hi":"मज़बूत अपट्रेंड में सिर्फ़ RSI 70 से ऊपर होने पर बेचना। मज़बूत ट्रेंड हफ़्तों तक ओवरबॉट रह सकते हैं।"},"pairs":{"en":"Moving averages (trend direction) and Bollinger Bands (range edges).","hi":"मूविंग एवरेज (ट्रेंड की दिशा) और बोलिंगर बैंड (रेंज की सीमाएँ)।"}},{"id":"macd","file":"macd.svg","category":"momentum","name":{"en":"MACD","hi":"MACD"},"what":{"en":"The difference between a 12-period and a 26-period EMA (the MACD line), its 9-period EMA (the signal line), and the histogram between them.","hi":"12-अवधि और 26-अवधि EMA का अंतर (MACD रेखा), उसका 9-अवधि EMA (सिग्नल रेखा), और इनके बीच का हिस्टोग्राम।"},"settings":{"en":"12, 26, 9.","hi":"12, 26, 9।"},"when":{"en":"To catch momentum shifts and trend changes in trending markets. Good for swing trades of days to weeks.","hi":"ट्रेंडिंग बाज़ार में मोमेंटम बदलाव और ट्रेंड परिवर्तन पकड़ने के लिए। दिनों से हफ़्तों के स्विंग ट्रेड के लिए अच्छा।"},"how":{"en":"Buy when the MACD line crosses above the signal line, ideally below the zero line (a pullback in an uptrend). Sell or exit on the opposite cross. Shrinking histogram bars warn that momentum is fading before the cross happens.","hi":"ख़रीदें जब MACD रेखा सिग्नल रेखा को ऊपर पार करे, आदर्श रूप से शून्य रेखा के नीचे (अपट्रेंड में पुलबैक)। विपरीत क्रॉस पर बेचें या बाहर निकलें। घटते हिस्टोग्राम बार बताते हैं कि क्रॉस होने से पहले मोमेंटम कमज़ोर हो रहा है।"},"mistake":{"en":"Trading every cross in a sideways market. Crosses there are random and cause repeated small losses (whipsaws).","hi":"साइडवे बाज़ार में हर क्रॉस पर ट्रेड करना। वहाँ क्रॉस अनियमित होते हैं और बार-बार छोटे नुकसान (व्हिपसॉ) देते हैं।"},"pairs":{"en":"ADX (confirm a trend exists) and volume (confirm the move).","hi":"ADX (ट्रेंड मौजूद है या नहीं) और वॉल्यूम (चाल की पुष्टि)।"}},{"id":"stochastic","file":"stochastic.svg","category":"momentum","name":{"en":"Stochastic oscillator","hi":"स्टोकेस्टिक ऑसिलेटर"},"what":{"en":"Shows where the latest close sits within the recent high-low range. %K is the fast line; %D is its smoothed version.","hi":"दिखाता है कि नवीनतम क्लोज़ हाल की हाई-लो रेंज में कहाँ है। %K तेज़ रेखा है; %D उसका सुचारु रूप।"},"settings":{"en":"14, 3, 3. Levels: 80 (overbought), 20 (oversold).","hi":"14, 3, 3। स्तर: 80 (ओवरबॉट), 20 (ओवरसोल्ड)।"},"when":{"en":"In sideways or mildly trending markets, to time entries near the edges of the range.","hi":"साइडवे या हल्के ट्रेंड वाले बाज़ार में, रेंज की सीमाओं के पास एंट्री का समय तय करने के लिए।"},"how":{"en":"Buy when %K crosses above %D while both are below 20. Sell when %K crosses below %D while both are above 80. In a strong trend, ignore the overbought signal and use it only for pullbacks in the trend direction.","hi":"ख़रीदें जब दोनों 20 से नीचे हों और %K, %D को ऊपर पार करे। बेचें जब दोनों 80 से ऊपर हों और %K, %D को नीचे पार करे। मज़बूत ट्रेंड में ओवरबॉट संकेत को नज़रअंदाज़ करें और केवल ट्रेंड की दिशा में पुलबैक के लिए इस्तेमाल करें।"},"mistake":{"en":"Using it alone in a strong trend, where it stays in overbought for long periods and gives early sell signals.","hi":"मज़बूत ट्रेंड में इसे अकेले इस्तेमाल करना, जहाँ यह लंबे समय तक ओवरबॉट रहता है और जल्दी बिक्री संकेत देता है।"},"pairs":{"en":"A moving average for trend direction; use the stochastic only to time entries.","hi":"ट्रेंड की दिशा के लिए मूविंग एवरेज; स्टोकेस्टिक केवल एंट्री का समय तय करने के लिए।"}},{"id":"bollinger-bands","file":"bollinger-bands.svg","category":"volatility","name":{"en":"Bollinger Bands","hi":"बोलिंगर बैंड"},"what":{"en":"A 20-period moving average (middle line) with upper and lower bands two standard deviations away. The bands widen when volatility rises and narrow when it falls.","hi":"20-अवधि मूविंग एवरेज (मध्य रेखा) और दो मानक विचलन दूर ऊपरी व निचले बैंड। अस्थिरता बढ़ने पर बैंड चौड़े और घटने पर संकरे होते हैं।"},"settings":{"en":"20 periods, 2 standard deviations.","hi":"20 अवधि, 2 मानक विचलन।"},"when":{"en":"To spot volatility squeezes before breakouts, and to find range-bound entries.","hi":"ब्रेकआउट से पहले अस्थिरता के संकुचन (squeeze) को पहचानने और रेंज में एंट्री खोजने के लिए।"},"how":{"en":"Squeeze: when the bands are at their narrowest for a while, wait for a close outside a band with rising volume. Range: buy near the lower band if RSI is below 30 and the candle turns up, target the middle line. In a strong trend, price can 'walk' along the upper band; do not sell just for touching it.","hi":"स्क्वीज़: जब बैंड कुछ समय तक सबसे संकरे हों, तो बढ़ते वॉल्यूम के साथ बैंड के बाहर क्लोज़ का इंतज़ार करें। रेंज: RSI 30 से नीचे और कैंडल ऊपर मुड़े तो निचले बैंड के पास ख़रीदें, मध्य रेखा तक लक्ष्य। मज़बूत ट्रेंड में कीमत ऊपरी बैंड के साथ 'चल' सकती है; सिर्फ़ छूने पर न बेचें।"},"mistake":{"en":"Treating a touch of a band as a reversal signal. Price can touch or pierce the bands many times during a trend.","hi":"बैंड को छूने को पलटाव संकेत मानना। ट्रेंड के दौरान कीमत बैंड को कई बार छू या पार कर सकती है।"},"pairs":{"en":"RSI (oversold or overbought at the edge) and volume (breakout confirmation).","hi":"RSI (किनारे पर ओवरसोल्ड या ओवरबॉट) और वॉल्यूम (ब्रेकआउट की पुष्टि)।"}},{"id":"atr","file":"atr.svg","category":"volatility","name":{"en":"ATR (Average True Range)","hi":"ATR (एवरेज ट्रू रेंज)"},"what":{"en":"The average size of daily price ranges, including gaps. It measures volatility in rupees, not direction.","hi":"अंतराल (gaps) सहित दैनिक कीमत रेंज का औसत आकार। यह दिशा नहीं, अस्थिरता को रुपयों में मापता है।"},"settings":{"en":"14 periods.","hi":"14 अवधि।"},"when":{"en":"To set stop-loss distances and position sizes that fit how much the stock normally moves. Use it for every trade.","hi":"स्टॉप-लॉस की दूरी और पोज़िशन साइज़ तय करने के लिए, जो शेयर की सामान्य चाल के अनुरूप हों। हर ट्रेड के लिए उपयोगी।"},"how":{"en":"Stop distance = 2 × ATR below the entry (for a long trade). Position size = maximum loss ÷ (2 × ATR). Example: entry ₹250, ATR ₹4, stop ₹242 (2 × ATR = ₹8 below). With ₹1,000 maximum loss, size = 1,000 ÷ 8 = 125 shares. Targets of 2 to 3 × ATR keep the reward in proportion.","hi":"स्टॉप की दूरी = एंट्री से नीचे 2 × ATR (लॉन्ग ट्रेड के लिए)। पोज़िशन साइज़ = अधिकतम नुकसान ÷ (2 × ATR)। उदाहरण: एंट्री ₹250, ATR ₹4, स्टॉप ₹242 (2 × ATR = ₹8 नीचे)। ₹1,000 अधिकतम नुकसान पर साइज़ = 1,000 ÷ 8 = 125 शेयर। 2 से 3 × ATR का टारगेट इनाम को अनुपात में रखता है।"},"mistake":{"en":"Using a fixed stop in rupees on every stock. A volatile stock needs a wider stop, or normal noise will stop you out.","hi":"हर शेयर पर रुपयों में एक तय स्टॉप लगाना। ज़्यादा अस्थिर शेयर को चौड़ा स्टॉप चाहिए, वरना सामान्य उतार-चढ़ाव आपको बाहर कर देगा।"},"pairs":{"en":"Any entry signal above, for the stop and size.","hi":"ऊपर का कोई भी एंट्री संकेत, स्टॉप और साइज़ के लिए।"}},{"id":"adx","file":"adx.svg","category":"trend","name":{"en":"ADX (trend strength)","hi":"ADX (ट्रेंड की ताकत)"},"what":{"en":"Measures how strong a trend is, on a 0 to 100 scale. It does not show direction. The +DI and -DI lines show which side is stronger.","hi":"0 से 100 के पैमाने पर ट्रेंड कितना मज़बूत है, यह मापता है। यह दिशा नहीं दिखाता। +DI और -DI रेखाएँ बताती हैं कि कौन सी ओर ज़्यादा मज़बूत है।"},"settings":{"en":"14 periods. Levels: 20 (weak or range), 25 (trend).","hi":"14 अवधि। स्तर: 20 (कमज़ोर या रेंज), 25 (ट्रेंड)।"},"when":{"en":"To choose your toolkit: trend tools when ADX is above 25 and rising, range tools when it is below 20.","hi":"अपना टूलकिट चुनने के लिए: ADX 25 से ऊपर और बढ़ रहा हो तो ट्रेंड टूल, 20 से नीचे हो तो रेंज टूल।"},"how":{"en":"ADX above 25 and rising with +DI above -DI: use moving-average pullbacks or breakouts (long side). ADX below 20: avoid trend-following entries and use RSI or Bollinger reversals near the range edges. A falling ADX from a high level often means the trend is tiring.","hi":"ADX 25 से ऊपर और बढ़ रहा हो, और +DI, -DI से ऊपर हो: मूविंग एवरेज पुलबैक या ब्रेकआउट (लॉन्ग साइड) इस्तेमाल करें। ADX 20 से नीचे: ट्रेंड-फ़ॉलोइंग एंट्री से बचें, रेंज के किनारों पर RSI या बोलिंगर रिवर्सल इस्तेमाल करें। ऊँचे स्तर से गिरता ADX अक्सर बताता है कि ट्रेंड थक रहा है।"},"mistake":{"en":"Reading ADX as a buy or sell signal. It only tells you how strong a trend is.","hi":"ADX को ख़रीद या बिक्री संकेत समझना। यह केवल बताता है कि ट्रेंड कितना मज़बूत है।"},"pairs":{"en":"Moving averages or breakouts (for direction) and ATR (for stops).","hi":"मूविंग एवरेज या ब्रेकआउट (दिशा के लिए) और ATR (स्टॉप के लिए)।"}},{"id":"volume","file":"volume.svg","category":"volume","name":{"en":"Volume","hi":"वॉल्यूम"},"what":{"en":"The number of shares traded in a period. It shows how much participation supports a price move.","hi":"किसी अवधि में ट्रेड हुए शेयरों की संख्या। यह बताता है कि कीमत की चाल को कितनी भागीदारी का समर्थन है।"},"settings":{"en":"Compare with a 20-period average volume.","hi":"20-अवधि के औसत वॉल्यूम से तुलना करें।"},"when":{"en":"To confirm breakouts, reversals and trend moves. Always check it alongside any price signal.","hi":"ब्रेकआउट, पलटाव और ट्रेंड चालों की पुष्टि के लिए। हर कीमत संकेत के साथ इसे जाँचें।"},"how":{"en":"Breakout: buy only if volume is at least 1.5 times its 20-day average on the breakout candle. A rally on falling volume is weak; expect a pullback. Very high volume at the end of a long fall (a climax) can mark exhaustion, but confirm with the next candles.","hi":"ब्रेकआउट: ख़रीदें केवल तब जब ब्रेकआउट कैंडल पर वॉल्यूम 20-दिन के औसत का कम से कम 1.5 गुना हो। घटते वॉल्यूम पर तेज़ी कमज़ोर है; पुलबैक की उम्मीद करें। लंबी गिरावट के अंत में बहुत ज़्यादा वॉल्यूम (क्लाइमैक्स) थकान का संकेत हो सकता है, पर अगली कैंडल से पुष्टि करें।"},"mistake":{"en":"Ignoring volume on a breakout and buying a move that has no buyers behind it.","hi":"ब्रेकआउट पर वॉल्यूम को अनदेखा करना और ऐसी चाल ख़रीदना जिसके पीछे ख़रीदार न हों।"},"pairs":{"en":"Any breakout or pattern (for confirmation), and OBV (for the trend of volume).","hi":"कोई भी ब्रेकआउट या पैटर्न (पुष्टि के लिए), और OBV (वॉल्यूम के ट्रेंड के लिए)।"}},{"id":"obv","file":"obv.svg","category":"volume","name":{"en":"OBV (On-Balance Volume)","hi":"OBV (ऑन-बैलेंस वॉल्यूम)"},"what":{"en":"A running total of volume: add the day's volume on up days, subtract it on down days. It shows whether volume is flowing in or out.","hi":"वॉल्यूम का चलता कुल: ऊपर के दिनों पर उस दिन का वॉल्यूम जोड़ें, नीचे के दिनों पर घटाएँ। यह बताता है कि वॉल्यूम अंदर आ रहा है या बाहर जा रहा है।"},"settings":{"en":"No settings. Look at its direction and highs.","hi":"कोई सेटिंग नहीं। इसकी दिशा और हाई देखें।"},"when":{"en":"To check if a trend has volume support, or to spot accumulation before a breakout.","hi":"यह जाँचने के लिए कि ट्रेंड को वॉल्यूम का समर्थन है या नहीं, या ब्रेकआउट से पहले संग्रहण (accumulation) पहचानने के लिए।"},"how":{"en":"Confirm: if price and OBV both make new highs, the uptrend has support. Warning: if price makes a new high but OBV does not, buyers are weakening (bearish divergence). Early signal: OBV breaks its own downtrend line while price is still flat, which can come before the price breakout.","hi":"पुष्टि: अगर कीमत और OBV दोनों नए हाई बनाएँ, तो अपट्रेंड को समर्थन है। चेतावनी: कीमत नया हाई बनाए पर OBV नहीं, तो ख़रीदार कमज़ोर हो रहे हैं (बियरिश डाइवर्जेंस)। शुरुआती संकेत: कीमत स्थिर हो तब OBV अपनी गिरावट की रेखा तोड़े, जो कीमत ब्रेकआउट से पहले आ सकता है।"},"mistake":{"en":"Reading OBV as a price level. Its actual number has no meaning; only its direction and highs matter.","hi":"OBV को कीमत स्तर समझना। इसकी वास्तविक संख्या का कोई अर्थ नहीं; केवल दिशा और हाई मायने रखते हैं।"},"pairs":{"en":"Moving averages (trend) and price highs (divergence).","hi":"मूविंग एवरेज (ट्रेंड) और कीमत के हाई (डाइवर्जेंस)।"}},{"id":"vwap","file":"vwap.svg","category":"volume","name":{"en":"VWAP (Volume Weighted Average Price)","hi":"VWAP (वॉल्यूम वेटेड एवरेज प्राइस)"},"what":{"en":"The average price for the day, weighted by volume. Many institutions use it as a fair-value benchmark. It resets every session.","hi":"दिन की औसत कीमत, वॉल्यूम के हिसाब से भारित। कई संस्थान इसे उचित मूल्य (fair value) के मानदंड के रूप में इस्तेमाल करते हैं। यह हर सत्र में नए सिरे से शुरू होता है।"},"settings":{"en":"Intraday: calculated from the session open.","hi":"इंट्राडे: सत्र के ओपन से गणना।"},"when":{"en":"For intraday trades, to see whether buyers or sellers control the session.","hi":"इंट्राडे ट्रेड के लिए, यह देखने के लिए कि सत्र पर ख़रीदार या विक्रेता नियंत्रण में हैं।"},"how":{"en":"Price above VWAP and holding: look for long entries on pullbacks to VWAP, with a stop just below it. Price below VWAP: avoid longs, or look for short setups on rallies back to VWAP. A stop that is too tight below VWAP gets hit by normal noise, so use ATR to size it.","hi":"कीमत VWAP के ऊपर और टिकी हो: VWAP तक पुलबैक पर लॉन्ग एंट्री खोजें, उसके ठीक नीचे स्टॉप के साथ। कीमत VWAP के नीचे हो: लॉन्ग से बचें, या VWAP तक उछाल पर शॉर्ट सेटअप खोजें। VWAP के नीचे बहुत तंग स्टॉप सामान्य उतार-चढ़ाव से बाहर कर देगा, इसलिए ATR से उसका आकार तय करें।"},"mistake":{"en":"Using VWAP on a swing trade or on a stock that opened with a big gap. Its value comes from one session's trading.","hi":"स्विंग ट्रेड पर या बड़े गैप से खुले शेयर पर VWAP इस्तेमाल करना। इसका मूल्य एक सत्र के ट्रेडिंग से आता है।"},"pairs":{"en":"Volume (is the move supported?) and ATR (for stops).","hi":"वॉल्यूम (चाल का समर्थन?) और ATR (स्टॉप के लिए)।"}},{"id":"fibonacci-retracement","file":"fibonacci.svg","category":"trend","name":{"en":"Fibonacci retracement","hi":"फ़िबोनाची रिट्रेसमेंट"},"what":{"en":"Horizontal levels at 23.6%, 38.2%, 50%, 61.8% and 78.6% of a prior swing. They estimate how far a pullback may go before the trend continues.","hi":"पिछले स्विंग के 23.6%, 38.2%, 50%, 61.8% और 78.6% पर क्षैतिज स्तर। ये अनुमान देते हैं कि ट्रेंड जारी रहने से पहले पुलबैक कहाँ तक जा सकता है।"},"settings":{"en":"Draw from a clear swing low to a swing high (uptrend), or the reverse for a downtrend. Most watched: 38.2%, 50%, 61.8%.","hi":"साफ़ स्विंग लो से स्विंग हाई तक खींचें (अपट्रेंड), डाउनट्रेंड में उल्टा। सबसे ज़्यादा देखे जाने वाले: 38.2%, 50%, 61.8%।"},"when":{"en":"To plan pullback entries in a trend, and to place targets or stops at likely support levels.","hi":"ट्रेंड में पुलबैक एंट्री की योजना के लिए, और संभावित सपोर्ट स्तरों पर टारगेट या स्टॉप रखने के लिए।"},"how":{"en":"Uptrend: wait for price to pull back to 38.2% to 61.8% of the swing, look for a bullish candle or RSI turn, buy, stop just below 61.8%. Target the previous high. A close below 78.6% often means the swing has failed.","hi":"अपट्रेंड: कीमत स्विंग के 38.2% से 61.8% तक लौटने का इंतज़ार, तेज़ी वाली कैंडल या RSI के मुड़ने पर ख़रीद, स्टॉप 61.8% के ठीक नीचे। टारगेट पिछला हाई। 78.6% के नीचे क्लोज़ अक्सर स्विंग की विफलता।"},"mistake":{"en":"Drawing the levels on random swings. Pick the clearest swing, and treat the levels as zones, not exact prices.","hi":"किसी भी स्विंग पर स्तर खींचना। सबसे साफ़ स्विंग चुनें और स्तरों को सटीक कीमत नहीं, ज़ोन मानें।"},"pairs":{"en":"A support candle or reversal pattern at the level, and volume.","hi":"स्तर पर सपोर्ट कैंडल या पलटाव पैटर्न, और वॉल्यूम।"}},{"id":"pivot-points","file":"pivot-points.svg","category":"trend","name":{"en":"Pivot points","hi":"पिवट पॉइंट्स"},"what":{"en":"Support and resistance levels calculated from the previous session's high, low and close: pivot (P), resistance (R1, R2) and support (S1, S2).","hi":"पिछले सत्र के हाई, लो और क्लोज़ से निकाले गए सपोर्ट और रेज़िस्टेंस स्तर: पिवट (P), रेज़िस्टेंस (R1, R2) और सपोर्ट (S1, S2)।"},"settings":{"en":"Classic formula: P = (High + Low + Close) ÷ 3, R1 = 2P − Low, S1 = 2P − High, R2 = P + (High − Low), S2 = P − (High − Low).","hi":"क्लासिक सूत्र: P = (हाई + लो + क्लोज़) ÷ 3, R1 = 2P − लो, S1 = 2P − हाई, R2 = P + (हाई − लो), S2 = P − (हाई − लो)।"},"when":{"en":"Intraday trading and short-term entries, when there is no clear chart structure yet. Many traders watch the same levels, which can make them self-fulfilling.","hi":"इंट्राडे ट्रेडिंग और छोटी अवधि की एंट्री, जब चार्ट की साफ़ संरचना अभी न हो। कई ट्रेडर एक ही स्तर देखते हैं, जिससे वे स्वयं-पूरे हो सकते हैं।"},"how":{"en":"Long: buy at S1 or P when price holds above and a bullish candle forms, target R1, stop below S1. Short (where permitted): sell at R1 with stop above R2. Use the pivot as the day's bias: above P is bullish.","hi":"लॉन्ग: S1 या P पर ख़रीदें जब कीमत ऊपर टिके और तेज़ी वाली कैंडल बने, टारगेट R1, स्टॉप S1 के नीचे। शॉर्ट (अनुमत हो तो): R1 पर बेचें, स्टॉप R2 के ऊपर। पिवट को दिन का रुझान मानें: P के ऊपर तेज़ी।"},"mistake":{"en":"Using pivots alone in a strong trend, where price runs through every level.","hi":"मज़बूत ट्रेंड में अकेले पिवट इस्तेमाल करना, जहाँ कीमत हर स्तर को पार कर जाती है।"},"pairs":{"en":"VWAP for the session's fair value, and volume.","hi":"सत्र के उचित मूल्य के लिए VWAP, और वॉल्यूम।"}},{"id":"supertrend","file":"supertrend.svg","category":"trend","name":{"en":"Supertrend","hi":"सुपरट्रेंड"},"what":{"en":"A trailing band built from ATR around the midpoint of each candle. It turns green below price in an uptrend and red above price in a downtrend.","hi":"हर कैंडल के मध्य बिंदु के चारों ओर ATR से बना ट्रेलिंग बैंड। अपट्रेंड में कीमत के नीचे हरा और डाउनट्रेंड में कीमत के ऊपर लाल होता है।"},"settings":{"en":"ATR period 10, multiplier 3 (common default).","hi":"ATR अवधि 10, गुणक 3 (आम डिफ़ॉल्ट)।"},"when":{"en":"To follow a trend and to trail a stop. Works best in trending markets; gives many false flips in sideways markets.","hi":"ट्रेंड का पीछा करने और स्टॉप ट्रेल करने के लिए। ट्रेंडिंग बाज़ार में सबसे अच्छा; साइडवे बाज़ार में कई झूठे फ़्लिप।"},"how":{"en":"Long: buy when the line flips from red to green (price closes above it). Stop: the green line, which moves up only. Exit when price closes below the line and it turns red.","hi":"लॉन्ग: जब लाइन लाल से हरी हो (कीमत उसके ऊपर क्लोज़), तब ख़रीदें। स्टॉप: हरी लाइन, जो केवल ऊपर जाती है। कीमत लाइन के नीचे क्लोज़ होकर लाल होने पर बाहर निकलें।"},"mistake":{"en":"Buying every flip. Use it with a higher-timeframe trend and volume, and avoid it on choppy days.","hi":"हर फ़्लिप पर ख़रीदना। इसे ऊँची समय-सीमा के ट्रेंड और वॉल्यूम के साथ इस्तेमाल करें, और उथल-पुथल वाले दिनों में नहीं।"},"pairs":{"en":"ADX (trend strength) and volume.","hi":"ADX (ट्रेंड की ताकत) और वॉल्यूम।"}},{"id":"parabolic-sar","file":"parabolic-sar.svg","category":"trend","name":{"en":"Parabolic SAR","hi":"पैराबोलिक SAR"},"what":{"en":"Dots placed above or below price that trail the move and accelerate as the trend continues. A dot switching side signals a possible reversal.","hi":"कीमत के ऊपर या नीचे लगे बिंदु जो चाल के साथ चलते हैं और ट्रेंड जारी रहने पर तेज़ होते हैं। बिंदु का पक्ष बदलना संभावित पलटाव का संकेत।"},"settings":{"en":"Acceleration step 0.02, maximum 0.2 (common defaults).","hi":"त्वरण स्टेप 0.02, अधिकतम 0.2 (आम डिफ़ॉल्ट)।"},"when":{"en":"In strong trends, to trail stops and to see when a trend may flip.","hi":"मज़बूत ट्रेंड में स्टॉप ट्रेल करने और यह देखने के लिए कि ट्रेंड कब पलट सकता है।"},"how":{"en":"Hold a long while dots sit below price. Move the stop to the latest dot each day. A switch of dots above price is an exit or reverse signal.","hi":"जब तक बिंदु कीमत के नीचे हों, लॉन्ग रखें। हर दिन स्टॉप नवीनतम बिंदु पर ले जाएँ। कीमत के ऊपर बिंदुओं का बदलना बाहर निकलने या पलटने का संकेत।"},"mistake":{"en":"Using it in a sideways market, where dots flip back and forth and cause repeated stop-outs.","hi":"साइडवे बाज़ार में इसका उपयोग, जहाँ बिंदु बार-बार पलटते हैं और बार-बार स्टॉप लगते हैं।"},"pairs":{"en":"A higher-timeframe trend filter such as a moving average.","hi":"मूविंग एवरेज जैसा ऊँची समय-सीमा का ट्रेंड फ़िल्टर।"}},{"id":"ichimoku-cloud","file":"ichimoku.svg","category":"trend","name":{"en":"Ichimoku cloud","hi":"इचिमोकू क्लाउड"},"what":{"en":"A complete trend view: Tenkan (fast average), Kijun (base average), and two spans plotted ahead that form a shaded cloud (Kumo). The cloud shows support and resistance.","hi":"पूरा ट्रेंड दृश्य: टेनकान (तेज़ औसत), किजुन (आधार औसत), और आगे खींची दो रेखाएँ जो छायांकित क्लाउड (कुमो) बनाती हैं। क्लाउड सपोर्ट और रेज़िस्टेंस दिखाता है।"},"settings":{"en":"Tenkan 9, Kijun 26, Senkou B 52, displacement 26 periods (classic).","hi":"टेनकान 9, किजुन 26, सेनकोउ B 52, विस्थापन 26 अवधि (क्लासिक)।"},"when":{"en":"To judge trend, support and momentum at a glance, especially on daily and weekly charts.","hi":"एक नज़र में ट्रेंड, सपोर्ट और मोमेंटम समझने के लिए, ख़ासकर डेली और वीकली चार्ट पर।"},"how":{"en":"Bullish: price above the cloud, Tenkan above Kijun, and a green (rising) cloud ahead. Buy pullbacks to Kijun while price stays above the cloud. Exit on a close back inside or below the cloud.","hi":"तेज़ी: कीमत क्लाउड के ऊपर, टेनकान किजुन के ऊपर, और आगे हरा (बढ़ता) क्लाउड। कीमत क्लाउड के ऊपर रहे तो किजुन तक पुलबैक पर ख़रीदें। क्लाउड के अंदर या नीचे क्लोज़ पर बाहर निकलें।"},"mistake":{"en":"Trading inside the cloud, where the signal is weakest. The settings are classic but can be changed for other markets.","hi":"क्लाउड के अंदर ट्रेड करना, जहाँ संकेत सबसे कमज़ोर होता है। सेटिंग क्लासिक हैं, पर अन्य बाज़ारों के लिए बदली जा सकती हैं।"},"pairs":{"en":"Volume for breakouts out of the cloud.","hi":"क्लाउड से बाहर के ब्रेकआउट के लिए वॉल्यूम।"}},{"id":"money-flow-index","file":"money-flow-index.svg","category":"volume","name":{"en":"Money flow index (MFI)","hi":"मनी फ़्लो इंडेक्स (MFI)"},"what":{"en":"An RSI-style oscillator that also uses volume. It measures buying and selling pressure from price times volume on a 0 to 100 scale.","hi":"RSI जैसा ऑसिलेटर, जो वॉल्यूम भी इस्तेमाल करता है। यह कीमत गुणा वॉल्यूम से ख़रीदने और बेचने का दबाव 0 से 100 के पैमाने पर मापता है।"},"settings":{"en":"14 periods. Above 80 overbought, below 20 oversold.","hi":"14 अवधि। 80 से ऊपर ओवरबॉट, 20 से नीचे ओवरसोल्ड।"},"when":{"en":"To confirm RSI signals with volume, and to spot divergence where price makes new highs but money flow does not.","hi":"RSI संकेतों की वॉल्यूम से पुष्टि के लिए, और डाइवर्जेंस पहचानने के लिए जहाँ कीमत नया हाई बनाए पर मनी फ़्लो नहीं।"},"how":{"en":"Bearish divergence: price makes a higher high but MFI makes a lower high, a warning to avoid new longs. Bullish divergence at a support level, with MFI turning up from below 20, supports a buy.","hi":"बियरिश डाइवर्जेंस: कीमत ऊँचा हाई बनाए पर MFI नीचा हाई, नए लॉन्ग से बचने की चेतावनी। सपोर्ट पर बुलिश डाइवर्जेंस, MFI 20 से नीचे से ऊपर मुड़े, तो ख़रीद का समर्थन।"},"mistake":{"en":"Treating overbought as an automatic sell in a strong uptrend.","hi":"मज़बूत अपट्रेंड में ओवरबॉट को अपने आप बिक्री संकेत मानना।"},"pairs":{"en":"RSI (to compare price momentum with volume-weighted flow).","hi":"RSI (कीमत के मोमेंटम की वॉल्यूम-भारित प्रवाह से तुलना के लिए)।"}}];
const GLOSSARY_TERMS = [{"cat":"basics","term":{"en":"Volume","hi":"वॉल्यूम"},"def":{"en":"The number of shares traded in a period. High volume means more participation.","hi":"किसी अवधि में ट्रेड हुए शेयरों की संख्या। ज़्यादा वॉल्यूम का मतलब ज़्यादा भागीदारी।"}},{"cat":"basics","term":{"en":"Volatility","hi":"अस्थिरता (वोलैटिलिटी)"},"def":{"en":"How much and how quickly a price moves. Higher volatility means bigger swings in both directions.","hi":"कीमत कितनी और कितनी तेज़ी से बदलती है। ज़्यादा अस्थिरता का मतलब दोनों दिशाओं में बड़े उतार-चढ़ाव।"}},{"cat":"technical","term":{"en":"Moving average","hi":"मूविंग एवरेज"},"def":{"en":"The average price over a set number of periods, used to smooth price and show trend.","hi":"तय अवधियों का औसत कीमत, जो चाल को सुचारु बनाता है और ट्रेंड दिखाता है।"}},{"cat":"technical","term":{"en":"RSI","hi":"RSI"},"def":{"en":"Relative Strength Index: a 0 to 100 momentum measure. Above 70 is often overbought; below 30 oversold.","hi":"रिलेटिव स्ट्रेंथ इंडेक्स: 0 से 100 का मोमेंटम मापक। 70 से ऊपर अक्सर ओवरबॉट; 30 से नीचे ओवरसोल्ड।"}},{"cat":"technical","term":{"en":"MACD","hi":"MACD"},"def":{"en":"Moving Average Convergence Divergence: a momentum indicator built from two moving averages and a signal line.","hi":"मूविंग एवरेज कन्वर्जेंस डाइवर्जेंस: दो मूविंग एवरेज और एक सिग्नल रेखा से बना मोमेंटम इंडिकेटर।"}},{"cat":"technical","term":{"en":"Divergence","hi":"डाइवर्जेंस"},"def":{"en":"When price and an indicator move in opposite directions, such as a new price high with a lower indicator high. It can warn that momentum is fading.","hi":"जब कीमत और इंडिकेटर उलटी दिशा में चलें, जैसे कीमत का नया हाई पर इंडिकेटर का नीचा हाई। यह मोमेंटम कमज़ोर होने की चेतावनी हो सकती है।"}}];
window.MP_PRACTICE = {"technical-indicators":[["chart","Add EMA 9/21, RSI and MACD to one chart. Mark three places where they agreed and three where they disagreed.","एक चार्ट पर EMA 9/21, RSI और MACD जोड़ें। तीन जगह चिह्नित करें जहाँ वे सहमत थे और तीन जहाँ असहमत।"],["screener","Run \"Oversold (RSI < 30)\" and \"MACD bullish crossover\" and check which results are still in a downtrend.","\"Oversold (RSI < 30)\" और \"MACD bullish crossover\" चलाएँ और देखें कि कौन-से नतीजे अब भी डाउनट्रेंड में हैं।"],["strategy","Backtest the \"EMA 9 / 21 crossover\" template on one stock, then on your watchlist. Compare it with buy-and-hold.","\"EMA 9 / 21 crossover\" टेम्पलेट को एक शेयर पर, फिर अपनी वॉचलिस्ट पर बैकटेस्ट करें। इसकी तुलना बाय-एंड-होल्ड से करें।"]]};
